    async function managedPickerFilesFromDirectory(directory,fs,path){
      const files=[];
      async function visit(current){
        const entries=await fs.promises.readdir(current,{withFileTypes:true});
        for(const entry of entries){
          const absolute=path.join(current,entry.name);
          if(entry.isDirectory())await visit(absolute);
          else if(entry.isFile()&&/\.(png|zip)$/i.test(entry.name))files.push({name:entry.name,webkitRelativePath:`${path.basename(directory)}/${path.relative(directory,absolute).split(path.sep).join('/')}`});
        }
      }
      await visit(directory);
      return files;
    }
    async function openManagedAddSelector(){
      const p=managed.find(item=>item.id===managedId)||managed[0];
      if(!p)return;
      const dialog=window.eagle?.dialog;
      if(typeof dialog?.showOpenDialog!=='function'){
        toast('请在 Eagle 插件窗口中操作','这里需要 Eagle 的原生选择器，才能在同一窗口选择文件或文件夹');
        return;
      }
      try{
        const result=await dialog.showOpenDialog({
          title:`项目新增包装 · ${p.project}`,
          buttonLabel:'导入',
          filters:[{name:'AEP、PNG、ZIP 文件',extensions:['aep','png','zip','json']}],
          properties:['openFile','openDirectory','multiSelections']
        });
        const selectedPaths=result?.canceled?[]:result?.filePaths||[];
        if(!selectedPaths.length)return;
        const fs=typeof require==='function'?require('fs'):null;
        const path=typeof require==='function'?require('path'):null;
        if(!fs||!path)throw new Error('当前插件窗口没有提供本地文件访问能力');
        const selected=await Promise.all(selectedPaths.map(async filePath=>({filePath,isDirectory:(await fs.promises.stat(filePath)).isDirectory()})));
        const directories=selected.filter(item=>item.isDirectory);
        if(directories.length&&(directories.length!==1||selected.length!==1)){
          toast('请一次选择一种来源','可以选择一个文件夹，或选择一个 AEP / 一组 PNG、ZIP 文件');
          return;
        }
        const aepPaths=selected.filter(item=>!item.isDirectory&&/\.aep$/i.test(item.filePath));
        if(aepPaths.length&&(aepPaths.length!==1||selected.length!==1)){
          toast('AEP 工程请单独选择','选择一个 AEP 工程，或改选 PNG、ZIP 文件/文件夹');
          return;
        }
        const source=directories.length?'folder':aepPaths.length?'aep':'files';
        prepareManagedAdd(p,source);
        const files=directories.length
          ?await managedPickerFilesFromDirectory(directories[0].filePath,fs,path)
          :selected.map(item=>({name:path.basename(item.filePath)}));
        if(source==='aep')aepSourceFileName=files[0]?.name||path.basename(aepPaths[0].filePath);
        routeHomeFiles(files,source==='aep'?'aep':source);
      }catch(error){
        toast('无法打开所选来源',error?.message||String(error),'error');
      }
    }
